            if (-not (Test-TaskForgeDate -Value $onOrBefore)) {
                throw '--on-or-before must be a valid date in YYYY-MM-DD format.'
            }
            $includeCompleted = $options.Contains('include-completed')
            $tasks = @(Read-TaskStore -Path $dataFile)
            $matching = @($tasks | Where-Object {
                $due = Get-TaskDueDate -Task $_
                if ($null -eq $due) { return $false }
                if (-not $includeCompleted -and ([string]$_.status) -ne 'pending') { return $false }
                return ($due -le $onOrBefore)
            })
            $sorted = @($matching | Sort-Object `
                @{ Expression = { Get-TaskDueDate -Task $_ } }, `
                @{ Expression = { [int]$_.id } })
            $report = @($sorted | ForEach-Object {
                $due = Get-TaskDueDate -Task $_
                [pscustomobject][ordered]@{
                    id = [int]$_.id
                    title = [string]$_.title
                    status = [string]$_.status
                    due = $due
                    overdue = ($due -lt $onOrBefore)
                }
            })
            if ($asJson) {
                Write-TaskForgeOutput -Value $report -AsJson $true
            }
